def normalize_language(code: str | None, fallback: str = "en") -> str:
    lang = str(code or "").strip().lower().split("-", 1)[0].split("_", 1)[0]
    return lang if lang in SUPPORTED_UI_LANGUAGES else fallback


def get_catalog(language_code: str | None) -> Dict[str, str]:
    lang = normalize_language(language_code)
    catalog = dict(TRANSLATIONS["en"])
    catalog.update(TRANSLATIONS.get(lang, {}))
    return catalog


def translate(language_code: str | None, key: str, **kwargs: Any) -> str:
    text = get_catalog(language_code).get(key, key)
    if kwargs:
        try:
            return text.format(**kwargs)
        except Exception:
            return text
    return text
